// Rich visual theme system for strategy decks.
// Each theme combines:
//   - palette: color set (bg / coverBg / text / muted / accent / accent2)
//   - coverStyle: how cover slides are laid out (~16 variants)
//   - contentStyle: how content slides are laid out (~16 variants)
//   - typography: title and body font + sizes
// 50+ themes generated by combining these dimensions.

export type Palette = {
  bg: string;
  bgAlt: string;          // soft variant of bg (for half-color, blocks, etc.)
  coverBg: string;        // cover/section background
  coverText: string;      // text on coverBg
  text: string;           // primary text on bg
  textMuted: string;      // secondary text on bg
  accent: string;         // primary accent (lines, bullets, dots)
  accent2: string;        // secondary accent (rare, for diagrams)
  dark: boolean;
};

export type PaletteId =
  | "corporate-navy"
  | "midnight-violet"
  | "deep-forest"
  | "wine"
  | "obsidian"
  | "tech-cyan"
  | "muted-slate"
  | "soft-cream"
  | "minimal-paper"
  | "warm-terracotta"
  | "fresh-green"
  | "blush"
  | "monochrome"
  | "earth"
  | "arctic"
  | "sunset";

