export type FontPairId = keyof typeof FONT_PAIRS;

// ─────────────────────── Theme spec ───────────────────────

export type DeckTheme = {
  id: string;
  name_he: string;
  name_en: string;
  palette: PaletteId;
  cover: CoverStyle;
  content: ContentStyle;
  font: FontPairId;
  titleScale?: number;   // multiplier 0.8–1.2
  bodyScale?: number;    // multiplier 0.8–1.2
};

