// Convenience accessors

export function getTheme(id: string): DeckTheme {
  return DECK_THEMES.find((t) => t.id === id) ?? DECK_THEMES[0];
}

export function getPalette(p: PaletteId): Palette {
  return PALETTES[p];
}

export function getFont(id: FontPairId): FontPair {
  return FONT_PAIRS[id];
}

// Convert "#abcdef" → "abcdef" (no hash) for pptxgenjs
export function noHash(c: string): string {
  return c.startsWith("#") ? c.slice(1) : c;
}
